'use client';
import { useBiodataStore } from '@/lib/store';
import { Button } from '@/components/ui/button';
import { UploadCloud } from 'lucide-react';

export function PhotoUploadForm({ onNext, onBack }: { onNext: () => void, onBack: () => void }) {
    const { biodata, updateBiodata } = useBiodataStore();

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                if (ev.target?.result) {
                    updateBiodata('photos', [ev.target.result as string]);
                }
            };
            reader.readAsDataURL(e.target.files[0]);
        }
    };

    return (
        <div className="max-w-xl mx-auto py-8 px-4">
            <div className="mb-8"><h2 className="text-2xl font-serif font-bold text-[#2A2A2A] border-l-4 border-[#C5A045] pl-4">Upload Photos</h2></div>

            <div className="border-2 border-dashed border-gray-300 rounded-xl p-12 text-center hover:bg-gray-50 transition-colors cursor-pointer relative">
                <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} accept="image/*" />
                <div className="flex flex-col items-center">
                    <div className="w-16 h-16 bg-[#FFFBF0] rounded-full flex items-center justify-center mb-4">
                        <UploadCloud className="w-8 h-8 text-[#C5A045]" />
                    </div>
                    <p className="font-medium text-gray-700">Click to upload or drag and drop</p>
                    <p className="text-sm text-gray-400 mt-1">Maximum 3 photos</p>
                </div>
            </div>

            <div className="mt-8 grid grid-cols-3 gap-4">
                {biodata.photos.map((src, i) => (
                    <div key={i} className="aspect-square rounded-lg overflow-hidden border">
                        <img src={src} alt="Preview" className="w-full h-full object-cover" />
                    </div>
                ))}
            </div>

            <div className="pt-8 flex justify-between">
                <Button type="button" variant="outline" onClick={onBack}>← Back</Button>
                <Button onClick={onNext} className="bg-[#C5A045] hover:bg-[#B39035] text-white">Next: Review →</Button>
            </div>
        </div>
    );
}

export function ReviewStep({ onNext, onBack }: { onNext: () => void, onBack: () => void }) {
    return (
        <div className="max-w-xl mx-auto py-8 px-4 text-center">
            <div className="mb-8"><h2 className="text-2xl font-serif font-bold text-[#2A2A2A] border-l-4 border-[#C5A045] pl-4">Review Your Biodata</h2></div>
            <p className="text-muted-foreground mb-8">Please check the preview on the right. If everything looks good, proceed to download.</p>

            <div className="pt-8 flex justify-between">
                <Button type="button" variant="outline" onClick={onBack}>← Back</Button>
                <Button onClick={onNext} className="bg-[#C5A045] hover:bg-[#B39035] text-white">Proceed to Download →</Button>
            </div>
        </div>
    )
}

export function DownloadStep({ onBack }: { onBack: () => void }) {
    return (
        <div className="max-w-xl mx-auto py-8 px-4 text-center">
            <div className="mb-8"><h2 className="text-2xl font-serif font-bold text-[#2A2A2A]">Ready to Download</h2></div>

            <div className="bg-white p-8 rounded-xl shadow border border-gray-100 mb-8">
                <h3 className="font-bold text-lg mb-2">Free Watermarked Version</h3>
                <p className="text-sm text-gray-500 mb-4">Download a standard quality PDF with ShaadiBio watermark.</p>
                <Button className="w-full" disabled>Download PDF (Coming Soon)</Button>
            </div>

            <div className="bg-[#FFFBF0] p-8 rounded-xl border border-[#C5A045] relative overflow-hidden">
                <div className="absolute top-0 right-0 bg-[#C5A045] text-white text-xs px-2 py-1 rounded-bl">RECOMMENDED</div>
                <h3 className="font-bold text-lg mb-2">Premium High-Quality</h3>
                <p className="text-sm text-gray-500 mb-4">Remove watermark + HD Quality + Priority Support</p>
                <Button className="w-full bg-[#C5A045] hover:bg-[#B39035] text-white" disabled>Pay ₹99 (Phase 2)</Button>
            </div>

            <div className="pt-8 flex justify-start">
                <Button type="button" variant="ghost" onClick={onBack}>← Back to Edit</Button>
            </div>
        </div>
    )
}

'use client';

import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useBiodataStore } from '@/lib/store';
import { educationCareerSchema, familyDetailsSchema, lifestyleSchema, partnerPreferencesSchema } from '@/lib/validation/schemas';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';

// A mapped object to get schema and keys dynamically could be cleaner, 
// but for explicit clarity I'll create separate components or a robust dynamic one.
// Let's create specific forms to avoid complexity.

export function EducationForm({ onNext, onBack }: { onNext: () => void, onBack: () => void }) {
    const { biodata, updateBiodata } = useBiodataStore();

    const form = useForm({
        resolver: zodResolver(educationCareerSchema),
        defaultValues: biodata.educationCareer as any,
        mode: 'onChange'
    });

    useEffect(() => {
        const sub = form.watch((val) => updateBiodata('educationCareer', val as any));
        return () => sub.unsubscribe();
    }, [form, updateBiodata]);

    return (
        <div className="max-w-xl mx-auto py-8 px-4">
            <div className="mb-8">
                <h2 className="text-2xl font-serif font-bold text-[#2A2A2A] border-l-4 border-[#C5A045] pl-4">Education & Career</h2>
            </div>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onNext)} className="space-y-6">
                    <FormField name="education" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>Highest Qualification</FormLabel><FormControl><Input placeholder="B.Tech Computer Science" {...field} /></FormControl><FormMessage /></FormItem>
                    )} />
                    <FormField name="educationDetail" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>College / University (Optional)</FormLabel><FormControl><Input placeholder="IIT Bombay" {...field} value={field.value || ''} /></FormControl><FormMessage /></FormItem>
                    )} />
                    <FormField name="occupation" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>Occupation</FormLabel><FormControl><Input placeholder="Software Engineer" {...field} /></FormControl><FormMessage /></FormItem>
                    )} />
                    <FormField name="occupationDetail" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>Company Name (Optional)</FormLabel><FormControl><Input placeholder="Google" {...field} value={field.value || ''} /></FormControl><FormMessage /></FormItem>
                    )} />
                    <FormField name="income" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>Annual Income (Optional)</FormLabel><FormControl><Input placeholder="15 LPA" {...field} value={field.value || ''} /></FormControl><FormMessage /></FormItem>
                    )} />

                    <div className="pt-8 flex justify-between">
                        <Button type="button" variant="outline" onClick={onBack}>← Back</Button>
                        <Button type="submit" className="bg-[#C5A045] hover:bg-[#B39035] text-white">Next: Family Details →</Button>
                    </div>
                </form>
            </Form>
        </div>
    );
}

export function FamilyDetailsForm({ onNext, onBack }: { onNext: () => void, onBack: () => void }) {
    const { biodata, updateBiodata } = useBiodataStore();

    const form = useForm({
        resolver: zodResolver(familyDetailsSchema),
        defaultValues: biodata.familyDetails as any,
        mode: 'onChange'
    });

    useEffect(() => {
        const sub = form.watch((val) => updateBiodata('familyDetails', val as any));
        return () => sub.unsubscribe();
    }, [form, updateBiodata]);

    return (
        <div className="max-w-xl mx-auto py-8 px-4">
            <div className="mb-8"><h2 className="text-2xl font-serif font-bold text-[#2A2A2A] border-l-4 border-[#C5A045] pl-4">Family Details</h2></div>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onNext)} className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                        <FormField name="fatherName" control={form.control} render={({ field }) => (
                            <FormItem><FormLabel>Father's Name</FormLabel><FormControl><Input {...field} /></FormControl></FormItem>
                        )} />
                        <FormField name="fatherOccupation" control={form.control} render={({ field }) => (
                            <FormItem><FormLabel>Father's Occupation</FormLabel><FormControl><Input {...field} /></FormControl></FormItem>
                        )} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <FormField name="motherName" control={form.control} render={({ field }) => (
                            <FormItem><FormLabel>Mother's Name</FormLabel><FormControl><Input {...field} /></FormControl></FormItem>
                        )} />
                        <FormField name="motherOccupation" control={form.control} render={({ field }) => (
                            <FormItem><FormLabel>Mother's Occupation</FormLabel><FormControl><Input {...field} /></FormControl></FormItem>
                        )} />
                    </div>
                    <FormField name="siblings" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>Siblings</FormLabel><FormControl><Input placeholder="1 Brother, 1 Sister" {...field} /></FormControl></FormItem>
                    )} />
                    <FormField name="familyType" control={form.control} render={({ field }) => (
                        <FormItem><FormLabel>Family Type</FormLabel><FormControl><Input placeholder="Nuclear / Joint" {...field} /></FormControl></FormItem>
                    )} />

                    <div className="pt-8 flex justify-between">
                        <Button type="button" variant="outline" onClick={onBack}>← Back</Button>
                        <Button type="submit" className="bg-[#C5A045] hover:bg-[#B39035] text-white">Next: Lifestyle →</Button>
                    </div>
                </form>
            </Form>
        </div>
    );
}

'use client';

import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useBiodataStore } from '@/lib/store';
import { personalDetailsSchema } from '@/lib/validation/schemas';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';

export function PersonalDetailsForm({ onNext }: { onNext: () => void }) {
    const { biodata, updateBiodata } = useBiodataStore();

    const form = useForm({
        resolver: zodResolver(personalDetailsSchema),
        defaultValues: biodata.personalDetails as any,
        mode: 'onChange',
    });

    // Autosave: Watch for changes and update store
    useEffect(() => {
        const subscription = form.watch((value) => {
            // @ts-ignore - partial update is safe here
            updateBiodata('personalDetails', value);
        });
        return () => subscription.unsubscribe();
    }, [form, updateBiodata]);

    const onSubmit = () => {
        onNext();
    };

    return (
        <div className="max-w-xl mx-auto py-8 px-4">
            <div className="mb-8">
                <h2 className="text-2xl font-serif font-bold text-[#2A2A2A] border-l-4 border-[#C5A045] pl-4">Personal Details</h2>
                <p className="text-muted-foreground mt-2 pl-5">Let's start with the basics for your biodata.</p>
            </div>

            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                    <FormField
                        control={form.control}
                        name="fullName"
                        render={({ field }) => (
                            <FormItem>
                                <FormLabel>Full Name</FormLabel>
                                <FormControl>
                                    <Input placeholder="Aditya Roy" {...field} />
                                </FormControl>
                                <FormMessage />
                            </FormItem>
                        )}
                    />

                    <div className="grid grid-cols-2 gap-4">
                        <FormField
                            control={form.control}
                            name="gender"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Gender</FormLabel>
                                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                                        <FormControl>
                                            <SelectTrigger>
                                                <SelectValue placeholder="Select" />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            <SelectItem value="male">Male</SelectItem>
                                            <SelectItem value="female">Female</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="height"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Height</FormLabel>
                                    <FormControl>
                                        {/* Simple Text for now, could be Select */}
                                        <Input placeholder="5 ft 9 in" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <FormField
                            control={form.control}
                            name="dateOfBirth"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Date of Birth</FormLabel>
                                    <FormControl>
                                        <Input type="date" {...field} value={field.value || ''} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <FormField
                            control={form.control}
                            name="age"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>OR Age</FormLabel>
                                    <FormControl>
                                        <Input
                                            type="number"
                                            placeholder="25"
                                            {...field}
                                            // Handle number coercion manually if needed, or rely on zod coerce
                                            onChange={e => field.onChange(e.target.valueAsNumber)}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <FormField
                            control={form.control}
                            name="city"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>City</FormLabel>
                                    <FormControl>
                                        <Input placeholder="Mumbai" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <FormField
                            control={form.control}
                            name="state"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>State</FormLabel>
                                    <FormControl>
                                        <Input placeholder="Maharashtra" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <FormField
                            control={form.control}
                            name="motherTongue"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Mother Tongue</FormLabel>
                                    <FormControl>
                                        <Input placeholder="Hindi" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <FormField
                            control={form.control}
                            name="religion"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Religion</FormLabel>
                                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                                        <FormControl>
                                            <SelectTrigger>
                                                <SelectValue placeholder="Select" />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            <SelectItem value="Hindu">Hindu</SelectItem>
                                            <SelectItem value="Muslim">Muslim</SelectItem>
                                            <SelectItem value="Sikh">Sikh</SelectItem>
                                            <SelectItem value="Christian">Christian</SelectItem>
                                            <SelectItem value="Jain">Jain</SelectItem>
                                            <SelectItem value="Other">Other</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <FormField
                            control={form.control}
                            name="caste"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Caste</FormLabel>
                                    <FormControl>
                                        <Input placeholder="Brahmin" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <FormField
                            control={form.control}
                            name="subcaste"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Subcaste (Optional)</FormLabel>
                                    <FormControl>
                                        <Input placeholder="Optional" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="pt-8 flex justify-end">
                        <Button type="submit" size="lg" className="bg-[#C5A045] hover:bg-[#B39035] text-white min-w-[200px]">
                            Next: Education & Career →
                        </Button>
                    </div>
                </form>
            </Form>
        </div>
    );
}

